import{_ as e,c as r,a2 as t,o}from"./chunks/framework.DpbDeoNR.js";const i="/pub-blog/assets/image-20250830082042717.CxczrO4-.png",s="/pub-blog/assets/image-20250830081833547.C7ZneCOP.png",n="/pub-blog/assets/image-20250830082128259.CbuNYO01.png",l="/pub-blog/assets/image-20250830082236922.Di3_JoaU.png",p="/pub-blog/assets/image-20250830095111424.Cokdm9oF.png",h="/pub-blog/assets/image-20250830095159281.qSpCT2ld.png",c="/pub-blog/assets/image-20250830095229296.D_X3WG88.png",m="/pub-blog/assets/image-20250830082802725.ByA-rSu7.png",d="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",g="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",P=JSON.parse('{"title":"2025年 华为鸿蒙创新赛比赛流程 全攻略","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md","filePath":"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md","lastUpdated":1757677612000}'),u={name:"鸿蒙开发技巧/2025年 华为鸿蒙创新赛比赛流程 全攻略/2025年 华为鸿蒙创新赛比赛流程 全攻略.md"};function b(_,a,f,q,k,x){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="_2025年-华为鸿蒙创新赛比赛流程-全攻略" tabindex="-1">2025年 华为鸿蒙创新赛比赛流程 全攻略 <a class="header-anchor" href="#_2025年-华为鸿蒙创新赛比赛流程-全攻略" aria-label="Permalink to &quot;2025年 华为鸿蒙创新赛比赛流程 全攻略&quot;">​</a></h1><p>各位开发者朋友们，大家好！</p><p>华为鸿蒙创新赛又来了！这可是每年开发者圈子里的重头戏，不仅有丰厚的奖金，更是展示自己技术实力、获得行业认可的绝佳机会。今天就来给大家详细拆解一下2025年的参赛流程，让你轻松上手，避免踩坑！</p><blockquote><p><a href="https://developer.huawei.com/consumer/cn/activity/digixActivity/digixcmsdetail/101750143863263087" target="_blank" rel="noreferrer">https://developer.huawei.com/consumer/cn/activity/digixActivity/digixcmsdetail/101750143863263087</a></p></blockquote><p><img src="'+i+'" alt="image-20250830082042717"></p><h2 id="参赛流程总览" tabindex="-1">参赛流程总览 <a class="header-anchor" href="#参赛流程总览" aria-label="Permalink to &quot;参赛流程总览&quot;">​</a></h2><p>为了让大家对整个参赛流程有个清晰的认识，我先画个流程图给大家看看：</p><p><img src="'+s+'" alt="image-20250830081833547"></p><p>通过这个流程图，相信大家对整个参赛过程已经有了直观的了解。接下来，我们逐步详细解析每个环节：</p><h2 id="第一步-报名注册" tabindex="-1">第一步：报名注册 <a class="header-anchor" href="#第一步-报名注册" aria-label="Permalink to &quot;第一步：报名注册&quot;">​</a></h2><p>首先当然是要报名啦，普通开发者和企业都可以报名参加！这一步相对简单，但也有几个注意事项：</p><p>✅ <strong>时间把控</strong>：关注官方公布的报名截止时间，千万别错过 ✅ <strong>资料准备</strong>：准备好个人或团队的基本信息 ✅ <strong>赛道选择</strong>：根据自己的技术栈和兴趣选择合适的赛道</p><p><img src="'+n+'" alt="image-20250830082128259"></p><h2 id="第二步-开发harmonyos-5应用并发布上架" tabindex="-1">第二步：开发HarmonyOS 5应用并发布上架 <a class="header-anchor" href="#第二步-开发harmonyos-5应用并发布上架" aria-label="Permalink to &quot;第二步：开发HarmonyOS 5应用并发布上架&quot;">​</a></h2><p>这是整个流程中最核心的部分，也是最考验技术功底的环节，简单总结就是有创意、有人文关怀的作品更好，同时需要体现鸿蒙新特性。另外，需要注意的是，<strong>先基于HarmonyOS5开发可以上架的作品，后面再接入6新特性 邀请测试即可。</strong></p><p><img src="'+l+'" alt="image-20250830082236922"></p><h2 id="第三步-应用上架策略" tabindex="-1">第三步：应用上架策略 <a class="header-anchor" href="#第三步-应用上架策略" aria-label="Permalink to &quot;第三步：应用上架策略&quot;">​</a></h2><p>这里有个重要的分叉路口，需要根据你的应用类型选择不同的策略：</p><h3 id="联网应用路线" tabindex="-1">联网应用路线 <a class="header-anchor" href="#联网应用路线" aria-label="Permalink to &quot;联网应用路线&quot;">​</a></h3><p>如果你的作品是要连接外网，那么就需要备案+软著：</p><ol><li>备案需要购买服务器</li><li>软著-正常流程2个月，现在时间是，2025年8月30日，那肯定来不及了。但是可以<strong>走易版权流程</strong></li></ol><h3 id="单机应用路线" tabindex="-1">单机应用路线 <a class="header-anchor" href="#单机应用路线" aria-label="Permalink to &quot;单机应用路线&quot;">​</a></h3><ul><li><strong>无需备案</strong>：流程相对简化</li><li><strong>无需软著</strong>：降低了准备门槛</li><li><strong>快速上线</strong>：审核周期较短</li></ul><p><strong>如果时间紧张，可以考虑先做单机版本快速上线，后续再迭代联网功能。</strong></p><h2 id="第四步-应用商店上架" tabindex="-1">第四步：应用商店上架 <a class="header-anchor" href="#第四步-应用商店上架" aria-label="Permalink to &quot;第四步：应用商店上架&quot;">​</a></h2><p>这个是需要提交作品发布上架到鸿蒙应用商店的。具体流程可以详细沟通。</p><p><img src="'+p+'" alt="image-20250830095111424"></p><h2 id="第五步-接入鸿蒙6新特性" tabindex="-1">第五步：接入鸿蒙6新特性 <a class="header-anchor" href="#第五步-接入鸿蒙6新特性" aria-label="Permalink to &quot;第五步：接入鸿蒙6新特性&quot;">​</a></h2><p>当你的作品成功上架后，恭喜你已经实现90%的功能了，接下来你需要使用DevEco 6版本的开发工具来接入鸿蒙6的新特性，然后继续迭代一些功能即可。</p><p>具体接入的新特性有哪些，可以查看这个：</p><blockquote><p><a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-releases/os-new-feature-600" target="_blank" rel="noreferrer">https://developer.huawei.com/consumer/cn/doc/harmonyos-releases/os-new-feature-600</a></p></blockquote><p><img src="'+h+'" alt="image-20250830095159281"></p><h2 id="第六步-申请白名单测试" tabindex="-1">第六步：申请白名单测试 <a class="header-anchor" href="#第六步-申请白名单测试" aria-label="Permalink to &quot;第六步：申请白名单测试&quot;">​</a></h2><p>这一步需要联系华为技术人员，提供你的资料给他们，他们为你开通白名单，你才可以提交 邀请测试，这一步也是需要时间的，所以请提前准备好。</p><h2 id="第七步-提交邀请测试" tabindex="-1">第七步：提交邀请测试 <a class="header-anchor" href="#第七步-提交邀请测试" aria-label="Permalink to &quot;第七步：提交邀请测试&quot;">​</a></h2><p>当对方通知你白名单已经开通，你就可以在agc平台上提交邀请测试了。</p><p><img src="'+c+'" alt="image-20250830095229296"></p><h2 id="第八步-编写展示材料" tabindex="-1">第八步：编写展示材料 <a class="header-anchor" href="#第八步-编写展示材料" aria-label="Permalink to &quot;第八步：编写展示材料&quot;">​</a></h2><p>测试通过后，需要准备最终的展示材料：</p><p><img src="'+m+'" alt="image-20250830082802725"></p><h2 id="第九步-最终提交与评比" tabindex="-1">第九步：最终提交与评比 <a class="header-anchor" href="#第九步-最终提交与评比" aria-label="Permalink to &quot;第九步：最终提交与评比&quot;">​</a></h2><p>最后的冲刺阶段：</p><ul><li><strong>材料检查</strong>：确保所有材料都准备齐全</li><li><strong>格式规范</strong>：按照要求的格式提交</li><li><strong>截止时间</strong>：在截止时间前完成提交</li><li><strong>心态调整</strong>：保持良好心态，等待结果</li></ul><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>华为鸿蒙创新赛不仅是一场技术竞赛，更是开发者成长和展示的舞台。无论最终是否获奖，参与的过程本身就是宝贵的学习和成长机会。</p><p>希望这份攻略能帮助到正在准备参赛的你！记住，技术是基础，创意是灵魂，坚持是关键！</p><hr><p>如果你觉得这份攻略对你有帮助，欢迎关注我们的技术分享平台，获取更多开发干货和行业资讯。也可以添加我的微信，一起交流鸿蒙开发技术，共同进步！</p><p>让我们一起在鸿蒙生态的浪潮中，书写属于开发者的精彩篇章！🚀</p><h2 id="以往文章" tabindex="-1">以往文章 <a class="header-anchor" href="#以往文章" aria-label="Permalink to &quot;以往文章&quot;">​</a></h2><ul><li><a href="https://mp.weixin.qq.com/s?__biz=MzI0NjY1MDY3Mg==&amp;mid=2247489342&amp;idx=1&amp;sn=15f4872e080ee3f86efdc32d6edfd979&amp;chksm=e813ff241c45844ae10e1fb352499b7253ae91ad932db71f17e86fa2251bb17251d5d840d1ab&amp;scene=126&amp;sessionid=1756092287&amp;subscene=91&amp;clicktime=1756092289&amp;enterid=1756092289#rd" target="_blank" rel="noreferrer">可可图片编辑 HarmonyOS 上架应用分享</a></li><li><a href="https://mp.weixin.qq.com/s/dacDD763JhrLkIS1V8rrdg" target="_blank" rel="noreferrer">可可图片编辑 HarmonyOS（2） 选择图片和保存到图库</a></li><li><a href="https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A" target="_blank" rel="noreferrer">懂你的HarmonyOS知识库更新了，已经来到10970个文档了</a></li><li><a href="https://mp.weixin.qq.com/s/AsieJTX8RkixgaKyDrzddg" target="_blank" rel="noreferrer">AI编程神器！Trae+Claude4.0 简单配置 让 HarmonyOS 开发效率飙升</a></li></ul><h2 id="近期活动" tabindex="-1">近期活动 <a class="header-anchor" href="#近期活动" aria-label="Permalink to &quot;近期活动&quot;">​</a></h2><p>最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，<a href="https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&amp;ha_sourceId=89000248" target="_blank" rel="noreferrer">加入我的班级</a>，考取成功有机会获得鸿蒙礼盒一份。</p><p><img src="'+d+'" alt="image-20250822223258675"></p><h2 id="联系我" tabindex="-1">联系我 <a class="header-anchor" href="#联系我" aria-label="Permalink to &quot;联系我&quot;">​</a></h2><p>可以加我微信，带你了解更多HarmonyOS相关的资讯。</p><p><img src="'+g+'" alt="wanshaoweixin"></p>',57)]))}const w=e(u,[["render",b]]);export{P as __pageData,w as default};
